function IS_EQUIV(f, A, B):
    fiber = empty map from B to list
    for a in A:
        append a to fiber[f(a)]
    for b in B:
        if length(fiber[b]) != 1:        # fiber not contractible
            return False
    return True                           # all fibers contractible

